preConditionHook:
// IS THE THREE-PUSH PATTERN ACCELERATING? Compare the SECOND push-to-push
// increment against the first. Accelerating (parabolic, V05-08) when the later
// increment is the larger; decelerating (shrinking stairs, waning momentum,
// V05-09) when it is the smaller -- and the second case is simply this rule
// NEGATED in the pane, which is why it is one rule and not two.
//
// perBar picks which of the two book readings is used: 1 divides each
// increment by the bars between its pivots, giving V05-08's
// trend-channel-line SLOPE; 0 leaves the raw price increments, which is
// V05-09's spelling. The divisor is guarded above zero because EasyLanguage
// raises a runtime divide-by-zero error, and the guard falls back to the raw
// increments rather than halting.
//
// Long reads the low pivots (three pushes down, the bull setup) and short the
// high pivots, the same side convention as the rest of the B03 family. The
// early increment must be positive: a pattern that is not pushing in one
// direction has nothing to accelerate.
//
// V05-08's 2 legs / 10 bars reversal expectation is guidance, not a condition,
// and is not encoded here.
//
// Pivot scan as in ThreePushPattern, inlined; the register lists Occurrence 3+
// as unmeasured, so the third push is found by hand. MEASURED
// (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min): the pivot bar is AT
// OR ABOVE the swingStrength OLDER bars and STRICTLY ABOVE the swingStrength
// NEWER bars -- bars-ago indexing, so the newer bars are the smaller k and
// take el_gt / el_lt, the older el_ge / el_le; confirmation lag exactly
// swingStrength bars; candidate offsets swingStrength .. lookbackBars - 1; the
// bars-ago count IS the pivot's bar index here, which is what the increments
// are divided by; the deepest bar touched is lookbackBars - 1 + swingStrength.
// No early break, matching the twin.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)swingStrength;
pivWindow = (int)lookbackBars;
perBarMode = (int)perBar;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
hiBar1 = -1;
hiBar2 = -1;
hiBar3 = -1;
loBar1 = -1;
loBar2 = -1;
loBar3 = -1;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) { hiPx1 = high[j]; hiBar1 = j; }
        if (nHiPiv == 2) { hiPx2 = high[j]; hiBar2 = j; }
        if (nHiPiv == 3) { hiPx3 = high[j]; hiBar3 = j; }
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) { loPx1 = low[j]; loBar1 = j; }
        if (nLoPiv == 2) { loPx2 = low[j]; loBar2 = j; }
        if (nLoPiv == 3) { loPx3 = low[j]; loBar3 = j; }
    }
}
accelUp = false;
accelDn = false;
if (nHiPiv == 3) {
    upLate = hiPx1 - hiPx2;
    upEarly = hiPx2 - hiPx3;
    upGapLate = hiBar2 - hiBar1;
    upGapEarly = hiBar3 - hiBar2;
    if (perBarMode == 1 && upGapLate > 0 && upGapEarly > 0) {
        upLate = upLate / upGapLate;
        upEarly = upEarly / upGapEarly;
    }
    accelUp = el_gt(upEarly, 0.0) && el_gt(upLate, upEarly * accelMultiple);
}
if (nLoPiv == 3) {
    dnLate = loPx2 - loPx1;
    dnEarly = loPx3 - loPx2;
    dnGapLate = loBar2 - loBar1;
    dnGapEarly = loBar3 - loBar2;
    if (perBarMode == 1 && dnGapLate > 0 && dnGapEarly > 0) {
        dnLate = dnLate / dnGapLate;
        dnEarly = dnEarly / dnGapEarly;
    }
    accelDn = el_gt(dnEarly, 0.0) && el_gt(dnLate, dnEarly * accelMultiple);
}
